use vstd::prelude::*;

verus! {

fn reverse(a: &mut Vec<i32>)
    ensures
        a@ == old(a)@.reverse(),
        a@.len() == old(a)@.len(),
{
    let n: usize = a.len();
    let mut i: usize = 0;

    while i < n / 2
        invariant
            n == a.len(),
            a@.len() == n,

            // Elements already swapped into their final places:
            forall|k: int|
                0 <= k < i ==> a@[k] == old(a)@[n as int - 1 - k],
            forall|k: int|
                n as int - i <= k < n as int ==> a@[k] == old(a)@[n as int - 1 - k],

            // Middle (not-yet-touched) region still equals the original:
            forall|k: int|
                i <= k && k < (n as int - i) ==> a@[k] == old(a)@[k],
        decreases (n / 2) - i,
    {
        let j: usize = n - 1 - i;

        // Swap a[i] and a[j]
        let tmp: i32 = a[i];
        a.set(i, a[j]);
        a.set(j, tmp);

        i = i + 1;
    }

    // From the loop invariants with i == n/2, we can conclude full reversal.
    assert(forall|k: int| 0 <= k < n as int ==> a@[k] == old(a)@[n as int - 1 - k]);
    assert(a@ == old(a)@.reverse());
}

} // verus!

